        int[] parent = new int[n];
        int[] order = new int[n];
        Arrays.fill(parent, -1);

        int top = 0;
        order[top++] = 0;
        parent[0] = -2;
        for (int i = 0; i < top; i++) {
            int v = order[i];
            for (int to : adj[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                order[top++] = to;
            }
        }

        int[] down = new int[n];
        int[] bestChild = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            int best = 0;
            for (int to : adj[v]) {
                if (to == parent[v]) continue;
                if (down[to] > 0 && down[to] > best) best = down[to];
            }
            down[v] = val[v] + best;
            bestChild[v] = best;
        }

        int[] up = new int[n];
        up[0] = 0;
        for (int i = 0; i < n; i++) {
            int v = order[i];
            int prefixBest = 0;
            int m = adj[v].size();
            int[] childDown = new int[m];
            int idx = 0;
            for (int to : adj[v]) {
                if (to == parent[v]) {
                    childDown[idx++] = 0;
                } else {
                    childDown[idx++] = Math.max(0, down[to]);
                }
            }
            int[] pref = new int[m];
            int[] suff = new int[m];
            for (int j = 0; j < m; j++) {
                prefixBest = Math.max(prefixBest, childDown[j]);
                pref[j] = prefixBest;
            }
            int suffixBest = 0;
            for (int j = m - 1; j >= 0; j--) {
                suffixBest = Math.max(suffixBest, childDown[j]);
                suff[j] = suffixBest;
            }
            idx = 0;
            for (int to : adj[v]) {
                if (to == parent[v]) {
                    idx++;
                    continue;
                }
                int bestOther = 0;
                if (idx > 0) bestOther = Math.max(bestOther, pref[idx - 1]);
                if (idx + 1 < m) bestOther = Math.max(bestOther, suff[idx + 1]);
                int candidate = val[v] + Math.max(0, up[v]);
                if (bestOther > 0) candidate = Math.max(candidate, val[v] + bestOther);
                up[to] = candidate;
                idx++;
            }
        }

        for (int i = 0; i < n; i++) {
            int best = Math.max(down[i], up[i]);
            if (best >= k) return true;
        }
        return false;
    }

