        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }

    static int n, k;
    static int[] a;
    static ArrayList<Integer>[] g;
    static int[] parent;
    static int[] depth;
    static int[][] up;
    static int LOG;
    static int[] order;
    static int[] pos;
    static int timer;

    static void dfsRoot(int v, int p) {
        parent[v] = p;
        for (int to : g[v]) {
            if (to == p) continue;
            depth[to] = depth[v] + 1;
            dfsRoot(to, v);
        }
    }

    static void buildLCA(int root) {
        parent = new int[n + 1];
        depth = new int[n + 1];
        dfsRoot(root, 0);
        LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        up = new int[LOG][n + 1];
        for (int v = 1; v <= n; v++) up[0][v] = parent[v];
        for (int j = 1; j < LOG; j++) {
            for (int v = 1; v <= n; v++) {
                int mid = up[j - 1][v];
                up[j][v] = mid == 0 ? 0 : up[j - 1][mid];
            }
        }
    }

    static int lca(int u, int v) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; j++) {
            if (((diff >> j) & 1) != 0) u = up[j][u];
        }
        if (u == v) return u;
        for (int j = LOG - 1; j >= 0; j--) {
            if (up[j][u] != up[j][v]) {
                u = up[j][u];
                v = up[j][v];
            }
        }
        return parent[u];
    }

    static int dist(int u, int v) {
        int w = lca(u, v);
        return depth[u] + depth[v] - 2 * depth[w];
    }

    static void dfsOrder(int v, int p) {
        order[++timer] = v;
        for (int to : g[v]) {
            if (to == p) continue;
            dfsOrder(to, v);
        }
    }

    static boolean can(int x) {
        // collect nodes with a[i] >= x
        int cnt = 0;
        for (int i = 1; i <= n; i++) {
            if (a[i] >= x) cnt++;
        }
        if (cnt < k) return false;

        // build induced forest on nodes with a[i] >= x
        // we need to find a component where we can order DFS to keep first k nodes all in this set
        // This is equivalent to: is there a connected component of size >= k in this induced forest?
        // Because we can root inside that component and visit all its nodes before leaving.
        boolean[] good = new boolean[n + 1];
        for (int i = 1; i <= n; i++) if (a[i] >= x) good[i] = true;

        boolean[] vis = new boolean[n + 1];
        int maxComp = 0;
        for (int i = 1; i <= n; i++) {
            if (good[i] && !vis[i]) {
                int size = 0;
                Deque<Integer> dq = new ArrayDeque<>();
                dq.add(i);
                vis[i] = true;
                while (!dq.isEmpty()) {
                    int v = dq.poll();
                    size++;
                    for (int to : g[v]) {
                        if (!vis[to] && good[to]) {
                            vis[to] = true;
                            dq.add(to);
                        }
                    }
                }
                if (size > maxComp) maxComp = size;
                if (maxComp >= k) return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        k = fs.nextInt();
        a = new int[n + 1];
        int minA = Integer.MAX_VALUE, maxA = 0;
        for (int i = 1; i <= n; i++) {
            a[i] = fs.nextInt();
            if (a[i] < minA) minA = a[i];
            if (a[i] > maxA) maxA = a[i];
        }
        g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        int lo = minA, hi = maxA, ans = minA;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (can(mid)) {
                ans = mid;
                lo = mid + 1;
            } else hi = mid - 1;
        }
        System.out.println(ans);
    }
}

