public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }

    static int n, k;
    static int[] a;
    static ArrayList<Integer>[] g;
    static boolean[] good;
    static int[] parent;
    static int[] depth;
    static int LOG;
    static int[][] up;
    static int[] goodCountSub;
    static int[] goodCountUp;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        k = fs.nextInt();
        a = new int[n + 1];
        int minA = Integer.MAX_VALUE, maxA = 0;
        for (int i = 1; i <= n; i++) {
            a[i] = fs.nextInt();
            minA = Math.min(minA, a[i]);
            maxA = Math.max(maxA, a[i]);
        }
        g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        parent = new int[n + 1];
        depth = new int[n + 1];
        LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        up = new int[LOG][n + 1];
        goodCountSub = new int[n + 1];
        goodCountUp = new int[n + 1];

        int lo = minA, hi = maxA, ans = minA;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (check(mid)) {
                ans = mid;
                lo = mid + 1;
            } else hi = mid - 1;
        }
        System.out.println(ans);
    }

    static boolean check(int x) {
        good = new boolean[n + 1];
        for (int i = 1; i <= n; i++) good[i] = a[i] >= x;

        // root tree at 1
        Arrays.fill(parent, 0);
        parent[1] = 0;
        depth[1] = 0;
        dfsRoot(1, 0);

        // build binary lifting table
        for (int v = 1; v <= n; v++) up[0][v] = parent[v] == 0 ? v : parent[v];
        for (int j = 1; j < LOG; j++) {
            for (int v = 1; v <= n; v++) {
                up[j][v] = up[j - 1][up[j - 1][v]];
            }
        }

        // compute goodCountSub (number of good nodes in subtree)
        dfsSub(1, 0);

        // compute goodCountUp (good nodes outside subtree, but in first k nodes when rooted at 1)
        dfsUp(1, 0);

        // For each node as root, compute number of good nodes in first k nodes
        for (int v = 1; v <= n; v++) {
            int cnt = countGoodFirstK(v);
            if (cnt == k) return true;
        }
        return false;
    }

    static void dfsRoot(int v, int p) {
        for (int to : g[v]) if (to != p) {
            parent[to] = v;
            depth[to] = depth[v] + 1;
            dfsRoot(to, v);
        }
    }

    static void dfsSub(int v, int p) {
        int cnt = good[v] ? 1 : 0;
        for (int to : g[v]) if (to != p) {
            dfsSub(to, v);
            cnt += goodCountSub[to];
        }
        goodCountSub[v] = cnt;
    }

    static void dfsUp(int v, int p) {
        int sumChildren = 0;
        for (int to : g[v]) if (to != p) sumChildren += goodCountSub[to];
        for (int to : g[v]) if (to != p) {
            // goodCountUp[to] = goodCountUp[v] + (good[v]?1:0) + (sumChildren - goodCountSub[to])
            goodCountUp[to] = goodCountUp[v] + (good[v] ? 1 : 0) + (sumChildren - goodCountSub[to]);
            dfsUp(to, v);
        }
    }

    // count good nodes among first k nodes in DFS when rooted at r
    static int countGoodFirstK(int r) {
        // total good nodes in tree
        int totalGood = goodCountSub[1];
        if (totalGood < k) return totalGood; // can't have k good nodes
        // we need to know how many of first k nodes are good.
        // With reordering, we can always visit all good nodes before bad ones.
        // So first min(k, totalGood) nodes are good.
        return Math.min(k, totalGood);
    }
}

