            int deg = g[v].size();
            int[] child = new int[deg];
            int idx = 0;
            for (int to : g[v]) if (to != parent[v]) child[idx++] = to;

            int[] prefG = new int[idx + 1];
            int[] prefB = new int[idx + 1];
            for (int j = 0; j < idx; j++) {
                int to = child[j];
                prefG[j + 1] = prefG[j] + goodSub[to];
                prefB[j + 1] = prefB[j] + badSub[to];
