        while ((1 << LOG) <= n) LOG++;
        up = new int[LOG][n];
        depth = new int[n];
        parent = new int[n];
        order = new int[n];
        pos = new int[n];
        minPref = new int[n];

        buildRootedTree(0);

        int low = 1, high = 1_000_000, ans = 1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (check(mid)) {
                ans = mid;
                low = mid + 1;
            } else high = mid - 1;
        }
        System.out.println(ans);
    }

    // Build rooted tree at 0, compute parent, depth, up, order, pos, minPref
    static void buildRootedTree(int root) {
        Arrays.fill(parent, -1);
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(root);
        parent[root] = root;
        depth[root] = 0;
        timer = 0;
        while (!stack.isEmpty()) {
            int v = stack.pop();
            order[timer] = v;
            pos[v] = timer++;
            for (int to : adj[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                depth[to] = depth[v] + 1;
                stack.push(to);
            }
        }
        for (int i = 0; i < n; i++) up[0][i] = parent[i];
        for (int j = 1; j < LOG; j++) {
            for (int i = 0; i < n; i++) {
                up[j][i] = up[j - 1][up[j - 1][i]];
            }
        }
        // compute minPref along parent chain from root
        minPref[root] = a[root];
        for (int i = 1; i < n; i++) {
            int v = order[i];
            minPref[v] = Math.min(a[v], minPref[parent[v]]);
        }
    }

    static int kthAncestor(int v, int k) {
        for (int j = 0; j < LOG; j++) {
            if (((k >> j) & 1) != 0) v = up[j][v];
        }
        return v;
    }

    static boolean check(int x) {
        int best = 0;
        for (int v = 0; v < n; v++) {
            if (a[v] < x) continue;
            int d = depth[v];
            if (d + 1 < k) continue;
            int anc = kthAncestor(v, k - 1);
            int minOnPath = minPref[v];
            if (anc != 0) {
                int parentAnc = parent[anc];
                minOnPath = Math.min(minOnPath, minPref[parentAnc]);
            }
            if (minOnPath >= x) {
                best = 1;
                break;
            }
        }
        return best == 1;
    }

    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

