        pos = new int[n + 1];

        bfsRoot(1);
        buildLCA();

        int[] sortedNodes = new int[n];
        for (int i = 0; i < n; i++) sortedNodes[i] = i + 1;
        Arrays.sort(sortedNodes, (x, y) -> Integer.compare(a[x], a[y]));

        int best = 0;
        int ptr = 0;
        for (int i = 0; i < n; i++) {
            int cand = a[sortedNodes[i]];
            while (ptr < n && a[sortedNodes[ptr]] < cand) ptr++;
            if (n - ptr < k) break;
            if (check(cand)) best = cand;
        }
        System.out.println(best);
    }

    static void bfsRoot(int root) {
        Arrays.fill(parent, -1);
        Queue<Integer> q = new ArrayDeque<>();
        q.add(root);
        parent[root] = 0;
        depth[root] = 0;
        timer = 0;
        while (!q.isEmpty()) {
            int v = q.poll();
            order[++timer] = v;
            pos[v] = timer;
            for (int to : adj[v]) {
                if (to == parent[v]) continue;
                parent[to] = v;
                depth[to] = depth[v] + 1;
                q.add(to);
            }
        }
    }

    static void buildLCA() {
        for (int v = 1; v <= n; v++) up[0][v] = parent[v];
        for (int j = 1; j < LOG; j++) {
            for (int v = 1; v <= n; v++) {
                int mid = up[j - 1][v];
                up[j][v] = mid == 0 ? 0 : up[j - 1][mid];
            }
        }
    }

    static int lca(int u, int v) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; j++) {
            if (((diff >> j) & 1) != 0) u = up[j][u];
        }
        if (u == v) return u;
        for (int j = LOG - 1; j >= 0; j--) {
            if (up[j][u] != up[j][v]) {
                u = up[j][u];
                v = up[j][v];
            }
        }
        return parent[u];
    }

    static int dist(int u, int v) {
        int w = lca(u, v);
        return depth[u] + depth[v] - 2 * depth[w];
    }

    static boolean check(int x) {
        List<Integer> S = new ArrayList<>();
        for (int i = 1; i <= n; i++) if (a[i] >= x) S.add(i);
        if (S.size() < k) return false;

        int u = S.get(0);
        int v = u;
        int maxd = 0;
        for (int node : S) {
            int d = dist(u, node);
            if (d > maxd) {
                maxd = d;
                v = node;
            }
        }
        int w = v;
        maxd = 0;
        for (int node : S) {
            int d = dist(v, node);
            if (d > maxd) {
                maxd = d;
                w = node;
            }
        }

        int cnt = 0;
        for (int node : S) {
            int d1 = dist(v, node);
            int d2 = dist(w, node);
            if (Math.max(d1, d2) <= k - 1) cnt++;
        }
        return cnt >= k;
    }

